WITH metrics AS (SELECT *, NTILE(4) OVER w_hist AS amount_bucket, ROW_NUMBER() OVER (PARTITION BY channel ORDER BY discount DESC, id) AS seq_no, ROUND(amount / SUM(amount) OVER (PARTITION BY customer_id), 4) AS amount_share, ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY amount, id) AS seq_no_2 FROM orders WHERE order_date BETWEEN '2024-02-28' AND '2025-02-01' WINDOW w_hist AS (PARTITION BY customer_id ORDER BY amount, id)) SELECT customer_id, CASE WHEN amount_bucket >= 7 THEN 'LARGE' ELSE 'SMALL' END AS amount_bucket_tier, SUM(shipping_fee) FILTER (WHERE status = 'CANCELLED') AS cancelled_total_shipping_fee, SUM(amount) AS total_amount, COUNT(DISTINCT store_id) AS distinct_store_ids, APPROX_PERCENTILE(shipping_fee, ARRAY(0.25, 0.5, 0.75)) AS shipping_fee_quartiles, COUNT(DISTINCT channel) AS distinct_channels FROM metrics GROUP BY customer_id, amount_bucket_tier HAVING COUNT(DISTINCT store_id) > 1 ORDER BY customer_id DESC
